from ranking import top_k


def test_orders_by_score_descending():
    assert top_k({"a": 0.1, "b": 0.9, "c": 0.5}, 3) == ["b", "c", "a"]


def test_respects_k():
    assert top_k({"a": 0.1, "b": 0.9, "c": 0.5}, 2) == ["b", "c"]


def test_ties_keep_insertion_order():
    # Equal scores keep the order they were inserted in.
    assert top_k({"b": 1.0, "a": 1.0}, 2) == ["b", "a"]


def test_empty():
    assert top_k({}, 3) == []

